using System.ComponentModel;
using ToonNet.Core.Models;
using ToonNet.Core.Parsing;

namespace ToonNet.Core.Serialization;

/// <summary>A value the reader has reached: a primitive, an object or an array.</summary>
/// <remarks>Supports code generated by <c>ToonNet.SourceGenerators</c>; not intended to be used directly.</remarks>
[EditorBrowsable(EditorBrowsableState.Never)]
public readonly struct ToonReaderValue
{
    internal readonly ToonParser.ValueRef Ref;

    internal ToonReaderValue(in ToonParser.ValueRef value) => Ref = value;
}

/// <summary>The state of reading an object's fields with <see cref="ToonReader.NextProperty"/>.</summary>
/// <remarks>Supports code generated by <c>ToonNet.SourceGenerators</c>; not intended to be used directly.</remarks>
[EditorBrowsable(EditorBrowsableState.Never)]
public struct ToonReaderObject
{
    internal ToonParser.ObjectCursor Cursor;
}

/// <summary>The state of reading an array's items with <see cref="ToonReader.NextItem"/>.</summary>
/// <remarks>Supports code generated by <c>ToonNet.SourceGenerators</c>; not intended to be used directly.</remarks>
[EditorBrowsable(EditorBrowsableState.Never)]
public struct ToonReaderArray
{
    internal ToonParser.ArrayCursor Cursor;
}

/// <summary>
///     Reads a TOON document for generated code, which reads <c>[ToonSerializable]</c> objects straight from the text
///     through it; values generated code does not read itself go to <see cref="ReadValue{T}"/>, which applies the
///     serializer's rules.
/// </summary>
/// <remarks>
///     Every check of the parser is made as the cursors advance; a value must be read (or skipped) completely before
///     the cursor that contains it advances. Supports code generated by <c>ToonNet.SourceGenerators</c>; not intended to
///     be used directly, and generated code needs <c>ToonNet.Core</c> of the same release.
/// </remarks>
[EditorBrowsable(EditorBrowsableState.Never)]
public sealed class ToonReader
{
    private readonly ToonParser _parser;
    private readonly IToonDeserializationHost _host;

    internal ToonReader(ToonParser parser, IToonDeserializationHost host)
    {
        _parser = parser;
        _host = host;
    }

    /// <summary>The deserialization options.</summary>
    public ToonSerializerOptions Options => _host.Options;

    /// <summary>Whether the value is an object.</summary>
    public bool IsObject(in ToonReaderValue value) => value.Ref.NodeKind == ToonNodeKind.Object;

    /// <summary>Whether the value is an array.</summary>
    public bool IsArray(in ToonReaderValue value) => value.Ref.NodeKind == ToonNodeKind.Array;

    /// <summary>Whether the value is <c>null</c>.</summary>
    public bool IsNull(in ToonReaderValue value) => value.Ref.NodeKind == ToonNodeKind.Primitive && _parser.IsNull(value.Ref);

    /// <summary>Starts reading the fields of an object value.</summary>
    public ToonReaderObject BeginObject(in ToonReaderValue value) => new() { Cursor = _parser.BeginObject(value.Ref) };

    /// <summary>Reads the next field of an object, or returns false at its end.</summary>
    public bool NextProperty(ref ToonReaderObject fields, out string key, out ToonReaderValue value)
    {
        var found = _parser.NextProperty(ref fields.Cursor, out key, out var valueRef);
        value = new ToonReaderValue(valueRef);
        return found;
    }

    /// <summary>Starts reading the items of an array value.</summary>
    public ToonReaderArray BeginArray(in ToonReaderValue value) => new() { Cursor = _parser.BeginArray(value.Ref) };

    /// <summary>The number of items to expect, for list capacities.</summary>
    public int CapacityHint(in ToonReaderArray items) => items.Cursor.CapacityHint;

    /// <summary>Reads the next item of an array, or returns false at its end.</summary>
    public bool NextItem(ref ToonReaderArray items, out ToonReaderValue item)
    {
        var found = _parser.NextItem(ref items.Cursor, out var itemRef);
        item = new ToonReaderValue(itemRef);
        return found;
    }

    /// <summary>
    ///     Reads a string, boolean or number token that is an exact match for <typeparamref name="T"/> (or its nullable
    ///     form) without boxing; returns false for anything else, which <see cref="ReadValue{T}"/> reads.
    /// </summary>
    public bool TryReadPrimitive<T>(in ToonReaderValue value, out T result) => ToonSerializer.TryReadToken(_parser, value.Ref, out result);

    /// <summary>Reads any value as <typeparamref name="T"/> with the serializer's rules.</summary>
    /// <param name="value">The value.</param>
    /// <param name="depth">The serializer depth of the value.</param>
    public T ReadValue<T>(in ToonReaderValue value, int depth) => (T)_host.ReadValue(value.Ref, typeof(T), depth)!;

    /// <summary>Reads a value into a <see cref="ToonValue"/> tree.</summary>
    public ToonValue BuildTree(in ToonReaderValue value) => _parser.BuildValue(value.Ref);

    /// <summary>Reads past a value, with the checks of reading it.</summary>
    public void Skip(in ToonReaderValue value) => _parser.Skip(value.Ref);

    /// <summary>
    ///     Gives up reading straight from the text (for example for a repeated key); the serializer then reads the
    ///     document through the <see cref="ToonValue"/> tree.
    /// </summary>
    public void Fallback() => _host.Fallback();
}

/// <summary>The serializer operations a <see cref="ToonReader"/> forwards for generated code.</summary>
internal interface IToonDeserializationHost
{
    ToonSerializerOptions Options { get; }

    object? ReadValue(in ToonParser.ValueRef value, Type targetType, int depth);

    void Fallback();
}

/// <summary>
///     Reads objects of one type straight from TOON text. Generated code registers one per <c>[ToonSerializable]</c>
///     type with a constructor it can use.
/// </summary>
/// <remarks>Supports code generated by <c>ToonNet.SourceGenerators</c>; not intended to be used directly.</remarks>
[EditorBrowsable(EditorBrowsableState.Never)]
public abstract class ToonObjectReader
{
    private protected ToonObjectReader() { }

    /// <summary>
    ///     What the generated code applies itself: 0 for code from generators before ToonNet 3.3; 1 when it also applies
    ///     the converters of the options, <see cref="ToonSerializerOptions.PropertyNameCaseInsensitive"/>,
    ///     <see cref="ToonSerializerOptions.UnmappedMemberHandling"/> and <see cref="ToonSerializerOptions.RespectRequiredMembers"/>.
    ///     The serializer leaves to reflection what older code does not apply.
    /// </summary>
    public virtual int FeatureLevel => 0;

    internal abstract object? ReadOf(ToonReader reader, in ToonReaderValue value, int depth);
}

/// <summary>Reads <typeparamref name="T"/> objects straight from TOON text, with the same result as the serializer.</summary>
/// <typeparam name="T">The type read.</typeparam>
/// <remarks>Supports code generated by <c>ToonNet.SourceGenerators</c>; not intended to be used directly.</remarks>
[EditorBrowsable(EditorBrowsableState.Never)]
public abstract class ToonObjectReader<T> : ToonObjectReader
{
    /// <summary>Creates the reader.</summary>
    protected ToonObjectReader() { }

    /// <summary>Reads an object value (other values are read by the serializer).</summary>
    /// <param name="reader">The reader.</param>
    /// <param name="value">The value.</param>
    /// <param name="depth">The serializer depth of the value.</param>
    public abstract T Read(ToonReader reader, in ToonReaderValue value, int depth);

    internal sealed override object? ReadOf(ToonReader reader, in ToonReaderValue value, int depth) => Read(reader, value, depth);
}
